from __future__ import absolute_import

from abc import ABCMeta, abstractproperty
import logging

from lxml import etree
from six.moves import UserDict

import six


@six.add_metaclass(ABCMeta)
class BaseScfcParser(object):
    """
    Base SCF Parser which provides general
    functionality to load and pre-parse scfc.
    """

    technology = None
    tree = None
    root = None

    def __init__(self, scfc, from_string=False, logger=None, parser=etree):
        """
        Base functionality for creating SCFCParser objects.

        :param scfc: mandatory argument, path to scfc
               file or it's content when "from_string=True"
        :param from_string: flag deciding whenever "scfc"
               parameter should be threaten as path or string
        :param logger: alternative logger, logging used if None
        :param parser: alternative parser, default is etree
        """
        self.logger = logger or logging
        if from_string:
            self.root = parser.fromstring(scfc)
            self.tree = etree.ElementTree(self.root)
        else:
            self.tree = parser.parse(scfc)
            self.root = self.tree.getroot()

    @property
    def ns_dict(self):
        """
        global namespace dictionary.
        created in order to centralize it because
        it's the same for scfc in every technology
        """
        return {"ns": self.root.xpath("namespace-uri(/*)")}

    @abstractproperty
    def smods(self):
        """
        List of system modules in given scfc.
        """

    @abstractproperty
    def rmods(self):
        """
        List of radio modules in given scfc.
        """

    @abstractproperty
    def alds(self):
        """
        List of ALD modules in given scfc.
        """

    @abstractproperty
    def cells(self):
        """
        Dictionary of cells in given scfc,
        slitted into technologies as keys and list of cells as values.
        """

    @abstractproperty
    def iot_cells(self):
        """
        Dictionary of IoT cells in given scfc,
        slitted into technologies as keys and list of cells as values.
        """

    @abstractproperty
    def units(self):
        """
        [WCDMA ONLY] List of units in scfc.
        """


class UniversalScfcParser(BaseScfcParser):
    """
    SCFCParser with methods working for every technology,
    based on similarities between SCFC content for every technology
    also base class for every technology-specific SCFCParser.
    """
    tech_to_cell_mapping = {"NR": "NRCELL", "LTE": "LCELL", "WCDMA": "LCELW", "GSM": "GNCEL"}
    tech_to_iot_cell_mapping = {"LTE": "NBIOT_FDD"}

    def get_managed_objects(self, class_name, full_distname=False):
        """
        Method for searching for managed objects.
        :param class_name: pattern for searching managed_objects.
        :param full_distname: specify whether to return full distnames
        :return: list of instances of ManagedObject c
        lass made from all managed_object found in SCFC
        """
        class_name = class_name.split(":")[-1]
        mng_objects = self.root.xpath(
            './/ns:managedObject[contains(@class, "{}")]'.format(class_name),
            namespaces=self.ns_dict)
        filtered = [ManagedObject(mo, self.ns_dict, full_distname) for mo in mng_objects if
                    class_name in mo.attrib["class"].split(":")]
        return filtered

    def save_scfc(self, dest):
        """
        Method for saving state of parser into given destination
        :param dest: path, file, file-like obj.
        """
        self.tree.write(dest, pretty_print=True, xml_declaration=True,
                        encoding='UTF-8')

    @property
    def smods(self):
        """
        System modules in given scfc
        :return: List of managed objects representing system modules
        """
        smod_objects = self.get_managed_objects("SMOD")
        return smod_objects

    @property
    def rmods(self):
        """
        Radio modules in given scfc
        :return: List of managed objects represeting radio modules
        """
        rmod_objects = self.get_managed_objects("RMOD")
        return rmod_objects

    @property
    def alds(self):
        """
        ALD modules in given scfc
        :return: List of managed objects represeting ALD modules
        """
        ald_objects = self.get_managed_objects("ALD")
        return ald_objects

    @property
    def cells(self):
        """
        Cells in given scfc
        :return: Dictionary of cells in given scfc,
        slitted into technologies as keys and list of cells as values.
        """
        cells = {}
        for tech, dist_name in self.tech_to_cell_mapping.items():
            cells[tech] = self.get_managed_objects(dist_name)
        return cells

    @property
    def iot_cells(self):
        """
        IoT Cells in given scfc
        :return: Dictionary of IoT cells in given scfc,
        slitted into technologies as keys and list of cells as values.
        """
        iot_cells = {}
        for tech, dist_name in self.tech_to_iot_cell_mapping.items():
            iot_cells[tech] = self.get_managed_objects(dist_name)
        return iot_cells

    @property
    def units(self):
        """
        This method is here only of compatibility reasons,
        but maybe some day it will return something useful.
        """
        return []

    @property
    def parameters(self):
        pnodes = self.root.xpath('.//ns:p', namespaces=self.ns_dict)
        parameters = []
        for p in pnodes:
            parameter_dict = {}
            parameter_dict.update(p.attrib)
            parameter_dict["value"] = p.text
            parameters.append(parameter_dict)
        return parameters


class ManagedObject(UserDict, object):
    """
    High-level representation of single ManagedObject.
    """

    def __init__(self, node_obj, ns_dict, full_distname=False):
        """
        Create new ManageObject.
        :param node_obj: object which represents xml tree node.
        :param ns_dict: namespace dictionary.
        :param full_distname: specify whether to return full distnames
        """
        UserDict.__init__(self)
        self.ns_dict = ns_dict
        self.node_obj = node_obj
        self.full_distname = full_distname
        self.update(self.params)
        self.update(self.attrib)

    @property
    def mutable_attrib(self):
        """
        Mutable version of ManagedObjects attributes representation,
        it's change should be included in tree automatically.

        :return: Mutable ManagedObjects attributes object of given node.
        """
        return self.node_obj.attrib

    @property
    def attrib(self):
        """
        Immutable attributes of ManagedObjects.
        :return: Dictionary of values of common ManagedObject node attributes.
        """
        return {"class": self.mutable_attrib["class"],
                "version": self.mutable_attrib["version"],
                "distName": self.mutable_attrib["distName"],
                "operation": self.mutable_attrib["operation"].split("/")[-1]}

    @property
    def mutable_params(self):
        """
        Mutable parameters objects.
        :return: List of mutable all
        (regardless of level of nestedness) parameters of given node.
        """
        return [param for param in
                self.node_obj.xpath(".//ns:p", namespaces=self.ns_dict) if
                "name" in param.attrib]

    @property
    def params(self):
        """
        Immutable parameters.
        :return: Dictionary of immutable (text) parameters of
        given node where key is parameter's "name" attribute
        """
        parameters = {param.attrib["name"]: param.text for param in
                      self.mutable_params}
        dist_name = self.node_obj.attrib["distName"]
        if not self.full_distname:
            dist_name = dist_name.split("/")[-1]
        parameters["distName"] = dist_name
        return parameters

    def __setitem__(self, key, value):
        """
        Implementation of dict-like setting functionality.
        :param key: attribute/parameter name, must exists in node attributes
        :param value: new attribute/parameter value
        """
        if key in self.attrib:
            self.mutable_attrib[key] = value
        elif key in self.params:
            paragraphs_to_change = self._filter_nodes(key)
            for p in paragraphs_to_change:
                p.text = value
        else:
            raise KeyError(
                "Can't set value of non existing attribute/parameter")
        super(ManagedObject, self).__setitem__(key, value)

    def _filter_nodes(self, key):
        matching_nodes = [pgf for pgf in self.mutable_params
                          if pgf.attrib["name"] == key]
        return matching_nodes

    def __str__(self):
        return "<{}: class: {} distname: {}>".format(self.__class__.__name__,
                                                     self.attrib["class"],
                                                     self.params["distName"])

    def __repr__(self):
        return str(self)
